<script setup lang="ts">
import { ref } from 'vue';import { CefEvent } from '@eclipse/shared';import { onClient,toClient } from '../core/bridge';
type Action={id:string;label:string;hint?:string};const visible=ref(false),title=ref('Взаимодействие'),actions=ref<Action[]>([]);
onClient(CefEvent.ContextMenu,p=>{const s=(p??{}) as {visible?:boolean;title?:string;actions?:Action[]};visible.value=s.visible===true;title.value=s.title??'Взаимодействие';actions.value=Array.isArray(s.actions)?s.actions:[];});
const choose=(id:string)=>{toClient(CefEvent.ContextAction,{id});visible.value=false;};
</script>
<template><Transition name="radial"><div v-if="visible" class="shade e-interactive" @click.self="choose('close')"><section class="radial"><div class="center"><small>CONTEXT</small><b>{{title}}</b></div><button v-for="(a,i) in actions" :key="a.id" :style="{'--i':i,'--n':actions.length}" @click="choose(a.id)"><strong>{{a.label}}</strong><span v-if="a.hint">{{a.hint}}</span></button></section></div></Transition></template>
<style scoped>.shade{position:fixed;inset:0;display:grid;place-items:center;background:rgba(2,4,8,.32);backdrop-filter:blur(2px)}.radial{position:relative;width:430px;height:430px}.center{position:absolute;inset:145px;display:grid;place-content:center;text-align:center;border-radius:50%;background:rgba(11,14,21,.96);border:1px solid var(--e-border);box-shadow:0 16px 50px #0008}.center small{font-size:9px;letter-spacing:.2em;color:var(--e-text-muted)}.center b{max-width:120px;font-size:13px}.radial button{--angle:calc(360deg / var(--n) * var(--i) - 90deg);position:absolute;left:50%;top:50%;width:128px;min-height:62px;transform:translate(-50%,-50%) rotate(var(--angle)) translateY(-164px) rotate(calc(-1 * var(--angle)));padding:8px;border:1px solid var(--e-border);border-radius:14px;background:rgba(14,18,27,.96);color:#fff;cursor:pointer}.radial button:hover{border-color:var(--e-accent);transform:translate(-50%,-50%) rotate(var(--angle)) translateY(-168px) rotate(calc(-1 * var(--angle))) scale(1.04)}.radial strong,.radial span{display:block}.radial strong{font-size:12px}.radial span{margin-top:3px;font-size:9px;color:var(--e-text-muted)}.radial-enter-active,.radial-leave-active{transition:.15s}.radial-enter-from,.radial-leave-to{opacity:0}</style>